from taf.internal.cloud.lcmaas.client.lcmaas.v1 import NeatsApi, NeatIn


class NeatV1(object):
    def __init__(self, api_client):
        self.neat_api_v1 = NeatsApi(api_client=api_client)

    def create_neat(self, name, mgmt_url, auth_url, username, password, client_id, ca_certs=None):
        if ca_certs is not None:
            ca_certs = 'cert=\n' + ca_certs
        neat_in = NeatIn(name=name,
                         mgmt_url=mgmt_url,
                         auth_url=auth_url,
                         username=username,
                         password=password,
                         client_id=client_id,
                         ca_certs=ca_certs)
        return self.neat_api_v1.add_neat(neat_in=neat_in)

    def get_neat_info_by_name(self, neat_name):
        return self.neat_api_v1.get_neat_by_name(neat_name=neat_name)

    def get_neats_info(self):
        return self.neat_api_v1.get_nea_ts()
